 12→<style>
 13→/* ========================================================================
 14→   CSS CUSTOM PROPERTIES
 15→   ======================================================================== */
 16→:root,
 17→html[data-theme="dark"] {
 18→  --bg: #0f1117;
 19→  --surface: #181c27;
 20→  --surface2: #1e2233;
