 30→  --shadow: 0 2px 12px rgba(0,0,0,0.3);
 31→  --input-bg: #141722;
 32→  --input-border: #2a2f42;
 33→}
 34→
 35→html[data-theme="light"] {
 36→  --bg: #f5f6fa;
 37→  --surface: #ffffff;
 38→  --surface2: #f0f1f5;
 39→  --border: #d1d5e0;
 40→  --text: #1a1c24;
 41→  --muted: #5f6780;
 42→  --accent: #2563eb;
 43→  --accent2: #0891b2;
 44→  --green: #16a34a;
 45→  --yellow: #ca8a04;
 46→  --red: #dc2626;
 47→  --grid-color: rgba(37, 99, 235, 0.05);
 48→  --shadow: 0 2px 12px rgba(0,0,0,0.08);
 49→  --input-bg: #ffffff;
 50→  --input-border: #d1d5e0;
 51→}
 52→
 53→/* ========================================================================
 54→   RESET & BASE
 55→   ======================================================================== */
 56→*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
 57→
 58→body {
 59→  font-family: 'IBM Plex Sans', sans-serif;
 60→  background: var(--bg);
 61→  color: var(--text);
 62→  line-height: 1.6;
 63→  min-height: 100vh;
 64→  position: relative;
 65→}
 66→
 67→body::before {
 68→  content: '';
 69→  position: fixed;
 70→  inset: 0;
 71→  background-image:
 72→    linear-gradient(var(--grid-color) 1px, transparent 1px),
 73→    linear-gradient(90deg, var(--grid-color) 1px, transparent 1px);
 74→  background-size: 40px 40px;
 75→  pointer-events: none;
 76→  z-index: 0;
 77→}
 78→
 79→/* ========================================================================
 80→   LAYOUT
 81→   ======================================================================== */
 82→.container {
 83→  max-width: 820px;
 84→  margin: 0 auto;
 85→  padding: 20px 16px 60px;
 86→  position: relative;
 87→  z-index: 1;
 88→}
 89→
 90→/* ========================================================================
 91→   HEADER
 92→   ======================================================================== */
 93→.header {
 94→  display: flex;
 95→  align-items: center;
 96→  gap: 12px;
 97→  margin-bottom: 20px;
 98→  flex-wrap: wrap;
 99→}
100→

100→
101→.logo {
102→  width: 44px; height: 44px;
103→  background: linear-gradient(135deg, var(--accent), var(--accent2));
104→  border-radius: 10px;
105→  display: flex; align-items: center; justify-content: center;
106→  font-family: 'IBM Plex Mono', monospace;
107→  font-weight: 700; font-size: 18px; color: #fff;
108→  flex-shrink: 0;
109→}
110→
111→.header-title {
112→  font-size: 22px; font-weight: 700;
113→  background: linear-gradient(135deg, var(--accent), var(--accent2));
114→  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
115→  background-clip: text;
116→}
117→
118→.version-badge {
119→  font-family: 'IBM Plex Mono', monospace;
120→  font-size: 11px; padding: 2px 8px;
121→  background: var(--surface2); border: 1px solid var(--border);
122→  border-radius: 20px; color: var(--muted);
123→}
124→
125→.header-actions {
126→  margin-left: auto;
127→  display: flex; gap: 8px; align-items: center;
128→}
129→
130→.header-btn {
131→  background: var(--surface); border: 1px solid var(--border);
132→  color: var(--text); border-radius: 8px; padding: 6px 12px;
133→  font-size: 13px; cursor: pointer; font-family: 'IBM Plex Mono', monospace;
134→  transition: background 0.2s;
135→}
136→.header-btn:hover { background: var(--surface2); }
137→
138→/* ========================================================================
139→   TAB BAR
140→   ======================================================================== */
141→.tab-bar {
142→  display: flex; gap: 6px; margin-bottom: 20px;
143→  background: var(--surface); border: 1px solid var(--border);
144→  border-radius: 12px; padding: 4px;
145→}
146→
147→.tab-btn {
148→  flex: 1; padding: 10px 16px;
149→  background: transparent; border: none; border-radius: 8px;
150→  color: var(--muted); font-size: 14px; font-weight: 600;
151→  cursor: pointer; transition: all 0.2s;
152→  font-family: 'IBM Plex Sans', sans-serif;
153→}
154→.tab-btn.active {
155→  background: linear-gradient(135deg, var(--accent), var(--accent2));
156→  color: #fff;
157→}
158→.tab-btn:not(.active):hover { color: var(--text); background: var(--surface2); }
159→
160→/* ========================================================================
161→   CARDS
162→   ======================================================================== */
163→.card {
164→  background: var(--surface);
165→  border: 1px solid var(--border);
166→  border-radius: 12px;
167→  padding: 20px;
168→  margin-bottom: 16px;
169→  box-shadow: var(--shadow);
170→}
171→
172→.card-title {
173→  font-size: 15px; font-weight: 600; margin-bottom: 12px;
174→  color: var(--text);
175→}
176→
177→/* ========================================================================
178→   FORM ELEMENTS
179→   ======================================================================== */
180→label {
181→  display: block; font-size: 13px; font-weight: 500;
182→  color: var(--muted); margin-bottom: 4px;
183→  font-family: 'IBM Plex Mono', monospace;
184→}
185→
186→select, input[type="text"], input[type="number"] {
187→  width: 100%; padding: 10px 12px;
188→  background: var(--input-bg); border: 1px solid var(--input-border);
189→  border-radius: 8px; color: var(--text); font-size: 14px;
190→  font-family: 'IBM Plex Mono', monospace;
191→  transition: border-color 0.2s;
192→}
193→select:focus, input:focus { outline: none; border-color: var(--accent); }
194→
195→.input-row {
196→  display: grid; grid-template-columns: 1fr 1fr; gap: 10px;
197→  margin-bottom: 10px;
198→}
199→
200→.input-group { margin-bottom: 10px; }
201→
202→.btn {
203→  width: 100%; padding: 12px 20px;
204→  background: linear-gradient(135deg, var(--accent), var(--accent2));
205→  border: none; border-radius: 8px; color: #fff;
206→  font-size: 15px; font-weight: 600; cursor: pointer;
207→  font-family: 'IBM Plex Sans', sans-serif;
208→  transition: opacity 0.2s;
209→}
210→.btn:hover { opacity: 0.9; }
211→.btn:disabled { opacity: 0.5; cursor: not-allowed; }
212→
213→.btn-secondary {
214→  background: var(--surface2); border: 1px solid var(--border);
215→  color: var(--text);
216→}
217→
218→.btn-sm { padding: 6px 14px; font-size: 13px; width: auto; }
219→
220→/* ========================================================================
221→   INPUT MODE TOGGLE
222→   ======================================================================== */
223→.input-mode-toggle {
224→  display: flex; gap: 4px; margin-bottom: 12px;
225→  background: var(--surface2); border-radius: 8px; padding: 3px;
226→}
227→
228→.input-mode-btn {
229→  flex: 1; padding: 6px 12px; border: none; border-radius: 6px;
230→  background: transparent; color: var(--muted); font-size: 13px;
231→  cursor: pointer; font-weight: 500; transition: all 0.2s;
232→}
233→.input-mode-btn.active { background: var(--surface); color: var(--text); box-shadow: var(--shadow); }
234→
235→/* ========================================================================
236→   FILE DROP ZONE
237→   ======================================================================== */
238→.drop-zone {
239→  border: 2px dashed var(--border); border-radius: 12px;
240→  padding: 30px; text-align: center; color: var(--muted);
241→  cursor: pointer; transition: border-color 0.2s;
242→  margin-bottom: 12px;
243→}
244→.drop-zone:hover, .drop-zone.dragover { border-color: var(--accent); color: var(--accent); }
245→
246→/* ========================================================================
247→   RESULTS TABLE
248→   ======================================================================== */
249→.results-table-wrap {
250→  overflow-x: auto; max-height: 400px; overflow-y: auto;
251→  border: 1px solid var(--border); border-radius: 8px;
252→  margin-bottom: 12px;
253→}
254→
255→.results-table {
256→  width: 100%; border-collapse: collapse; font-size: 13px;
257→  font-family: 'IBM Plex Mono', monospace;
258→}
259→.results-table th {
260→  position: sticky; top: 0; background: var(--surface2);
261→  padding: 8px 10px; text-align: left; font-weight: 600;
262→  border-bottom: 1px solid var(--border); white-space: nowrap;
263→}
264→.results-table td {
265→  padding: 6px 10px; border-bottom: 1px solid var(--border);
266→  white-space: nowrap;
267→}
268→.results-table tr:last-child td { border-bottom: none; }
269→
270→.col-input { background: rgba(37, 99, 235, 0.05); }
271→.col-output { background: rgba(34, 197, 94, 0.05); }
272→
273→/* ========================================================================
274→   POINTS LIST
275→   ======================================================================== */
276→.points-list { margin-bottom: 12px; }
277→
278→.point-row {
279→  display: flex; gap: 8px; align-items: center; margin-bottom: 6px;
280→}
281→.point-row input { flex: 1; }
282→
283→.point-row .remove-btn {
284→  width: 32px; height: 32px; border: 1px solid var(--border);
285→  border-radius: 6px; background: var(--surface2); color: var(--red);
286→  cursor: pointer; font-size: 16px; display: flex;
287→  align-items: center; justify-content: center; flex-shrink: 0;
288→}
289→
290→.point-counter {
291→  display: inline-block; background: var(--accent);
292→  color: #fff; border-radius: 12px; padding: 1px 8px;
293→  font-size: 12px; font-family: 'IBM Plex Mono', monospace;
294→  margin-left: 8px;
295→}
296→
297→/* ========================================================================
298→   ZONING VERDICT
299→   ======================================================================== */

