305→.verdict-yellow { background: rgba(234, 179, 8, 0.1); border: 1px solid var(--yellow); color: var(--yellow); }
306→.verdict-red { background: rgba(239, 68, 68, 0.1); border: 1px solid var(--red); color: var(--red); }
307→
308→.meta-grid {
309→  display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px;
310→  margin-bottom: 16px;
311→}
312→.meta-item label { font-size: 11px; margin-bottom: 2px; }
313→.meta-item .meta-value {
314→  font-family: 'IBM Plex Mono', monospace;
