320→  background: var(--surface2); border: 1px solid var(--border);
321→}
322→.risk-flag-header { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
323→.risk-badge {
324→  font-size: 11px; padding: 2px 8px; border-radius: 10px;
325→  font-weight: 600; font-family: 'IBM Plex Mono', monospace;
326→}
327→.risk-badge.high { background: rgba(239,68,68,0.15); color: var(--red); }
328→.risk-badge.medium { background: rgba(234,179,8,0.15); color: var(--yellow); }
329→.risk-badge.low { background: rgba(34,197,94,0.15); color: var(--green); }
330→
