358→/* ========================================================================
359→   MAP
360→   ======================================================================== */
361→.map-container {
362→  height: 300px; border-radius: 10px; overflow: hidden;
363→  border: 1px solid var(--border); margin-bottom: 12px;
364→}
365→
366→/* ========================================================================
367→   SPINNER
368→   ======================================================================== */
369→.spinner {
370→  display: none; text-align: center; padding: 20px;
371→}
372→.spinner.active { display: block; }
373→.spinner::after {
374→  content: ''; display: inline-block; width: 32px; height: 32px;
375→  border: 3px solid var(--border); border-top-color: var(--accent);
376→  border-radius: 50%; animation: spin 0.8s linear infinite;
377→}
378→@keyframes spin { to { transform: rotate(360deg); } }
379→
