382→   ======================================================================== */
383→.toast {
384→  position: fixed; bottom: 24px; right: 24px; z-index: 9999;
385→  background: var(--surface); border: 1px solid var(--border);
386→  color: var(--text); padding: 12px 20px; border-radius: 10px;
387→  box-shadow: var(--shadow); font-size: 14px;
388→  opacity: 0; transition: opacity 0.3s; pointer-events: none;
389→}
390→.toast.show { opacity: 1; pointer-events: auto; }
