.verdict-card {
  padding: 16px 20px; border-radius: 10px; margin-bottom: 16px;
  font-size: 16px; font-weight: 600;
}
.verdict-green { background: rgba(34, 197, 94, 0.1); border: 1px solid var(--green); color: var(--green); }
.verdict-yellow { background: rgba(234, 179, 8, 0.1); border: 1px solid var(--yellow); color: var(--yellow); }
.verdict-red { background: rgba(239, 68, 68, 0.1); border: 1px solid var(--red); color: var(--red); }

.meta-grid {
  display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px;
  margin-bottom: 16px;
}
.meta-item label { font-size: 11px; margin-bottom: 2px; }
.meta-item .meta-value {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 13px; font-weight: 500;
}

.risk-flag {
  padding: 12px; border-radius: 8px; margin-bottom: 8px;
  background: var(--surface2); border: 1px solid var(--border);
}
.risk-flag-header { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
.risk-badge {
  font-size: 11px; padding: 2px 8px; border-radius: 10px;
  font-weight: 600; font-family: 'IBM Plex Mono', monospace;
}
.risk-badge.high { background: rgba(239,68,68,0.15); color: var(--red); }
.risk-badge.medium { background: rgba(234,179,8,0.15); color: var(--yellow); }
.risk-badge.low { background: rgba(34,197,94,0.15); color: var(--green); }

.params-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
  margin-bottom: 12px;
}
.param-item {
  background: var(--surface2); padding: 10px; border-radius: 8px;
  border: 1px solid var(--border);
}
.param-item label { font-size: 11px; }
.param-item .param-value {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 15px; font-weight: 600;
}

.data-source {
  font-size: 12px; color: var(--muted);
  font-family: 'IBM Plex Mono', monospace;
  margin-bottom: 8px;
}

.disclaimer {
  font-size: 12px; color: var(--muted);
  font-style: italic; padding: 10px;
  background: var(--surface2); border-radius: 8px;
  border: 1px solid var(--border);
}

/* ========================================================================
   MAP
   ======================================================================== */
.map-container {
  height: 300px; border-radius: 10px; overflow: hidden;
  border: 1px solid var(--border); margin-bottom: 12px;
}

/* ========================================================================
   SPINNER
   ======================================================================== */
.spinner {
  display: none; text-align: center; padding: 20px;
}
.spinner.active { display: block; }
.spinner::after {
  content: ''; display: inline-block; width: 32px; height: 32px;
  border: 3px solid var(--border); border-top-color: var(--accent);
  border-radius: 50%; animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ========================================================================
   TOAST
   ======================================================================== */
.toast {
  position: fixed; bottom: 24px; right: 24px; z-index: 9999;
  background: var(--surface); border: 1px solid var(--border);
  color: var(--text); padding: 12px 20px; border-radius: 10px;
  box-shadow: var(--shadow); font-size: 14px;
  opacity: 0; transition: opacity 0.3s; pointer-events: none;
}
.toast.show { opacity: 1; pointer-events: auto; }

/* ========================================================================
   ADDRESS LINE
   ======================================================================== */
.address-line {
  font-size: 13px; color: var(--muted); margin-bottom: 12px;
  font-family: 'IBM Plex Mono', monospace;
}

/* ========================================================================
   EXPORT BAR
   ======================================================================== */
.export-bar {
  display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px;
}

/* ========================================================================
   TAB PANELS
   ======================================================================== */
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ========================================================================
   FEK LINK
   ======================================================================== */
a.fek-link { color: var(--accent); text-decoration: none; }
a.fek-link:hover { text-decoration: underline; }

/* ========================================================================
   RESPONSIVE
   ======================================================================== */
@media (max-width: 680px) {
  .header { gap: 8px; }
  .header-title { font-size: 18px; }
  .meta-grid { grid-template-columns: 1fr 1fr; }
  .params-grid { grid-template-columns: 1fr; }
  .input-row { grid-template-columns: 1fr; }
}

@media (max-width: 460px) {
  .container { padding: 12px 8px 40px; }
  .tab-btn { font-size: 12px; padding: 8px 8px; }
  .meta-grid { grid-template-columns: 1fr; }
  .header-actions { margin-left: 0; width: 100%; justify-content: flex-end; }
}
</style>
</head>
<body>

<div class="container">
  <!-- ===== HEADER ===== -->
  <div class="header">
    <div class="logo">TT</div>
    <span class="header-title">TopoTools</span>
    <span class="version-badge">v1.0</span>
    <div class="header-actions">
      <button class="header-btn" id="lang-toggle" onclick="toggleLanguage()">EN</button>
      <button class="header-btn" id="theme-toggle" onclick="toggleTheme()">&#9788;</button>
    </div>
  </div>

  <!-- ===== TAB BAR ===== -->
  <div class="tab-bar">
    <button class="tab-btn active" data-tab="convert" data-i18n="tab_convert" onclick="switchTab('convert')">Convert</button>
    <button class="tab-btn" data-tab="zoning" data-i18n="tab_zoning" onclick="switchTab('zoning')">Zoning</button>
  </div>

  <!-- ===== TAB 1: CONVERT ===== -->
  <div class="tab-panel active" id="tab-convert">
    <div class="card">
      <div class="card-title" data-i18n="convert_title">Coordinate Converter</div>

      <div class="input-row">
        <div class="input-group">
          <label data-i18n="input_system">Input System</label>
          <select id="convert-input-system" onchange="updateConvertInputFields()">
            <option value="egsa87">EGSA87</option>
            <option value="wgs84_dd">WGS84 DD</option>
            <option value="wgs84_dms">WGS84 DMS</option>
            <option value="ggrs87_geo">GGRS87 Geographic</option>
            <option value="htrs07_geo">HTRS07 Geographic</option>
            <option value="tm07">TM07</option>
          </select>
        </div>
        <div class="input-group">
          <label data-i18n="output_system">Output System</label>
          <select id="convert-output-system">
            <option value="all" data-i18n="all_systems">All Systems</option>
            <option value="egsa87">EGSA87</option>
            <option value="wgs84_dd">WGS84 DD</option>
            <option value="wgs84_dms">WGS84 DMS</option>
            <option value="ggrs87_geo">GGRS87 Geographic</option>
            <option value="htrs07_geo">HTRS07 Geographic</option>
            <option value="tm07">TM07</option>
          </select>
        </div>
      </div>

      <!-- Input mode toggle -->
      <div class="input-mode-toggle" id="convert-mode-toggle">
        <button class="input-mode-btn active" data-mode="manual" onclick="switchInputMode('convert','manual')" data-i18n="manual_entry">Manual Entry</button>
        <button class="input-mode-btn" data-mode="file" onclick="switchInputMode('convert','file')" data-i18n="file_upload">File Upload</button>
      </div>

      <!-- Manual entry -->
      <div id="convert-manual-mode">
        <div class="points-list" id="convert-points-list">
          <div class="point-row">
            <input type="text" class="point-name" placeholder="Name" style="max-width:80px;">

