702→function switchInputMode(tabPrefix, mode) {
703→  const toggle = document.getElementById(tabPrefix + '-mode-toggle');
704→  toggle.querySelectorAll('.input-mode-btn').forEach(b => b.classList.toggle('active', b.dataset.mode === mode));
705→  document.getElementById(tabPrefix + '-manual-mode').style.display = mode === 'manual' ? '' : 'none';
706→  document.getElementById(tabPrefix + '-file-mode').style.display = mode === 'file' ? '' : 'none';
707→}
