709→/* ========================================================================
710→   SHARED UTILITIES
711→   ======================================================================== */
712→function showToast(msg) {
713→  const el = document.getElementById('toast');
714→  el.textContent = msg;
715→  el.classList.add('show');
716→  setTimeout(() => el.classList.remove('show'), 2500);
717→}
