719→function escapeHtml(str) {
720→  const div = document.createElement('div');
721→  div.textContent = str;
722→  return div.innerHTML;
723→}
724→
725→function copyValue(text) {
726→  if (navigator.clipboard && navigator.clipboard.writeText) {
727→    navigator.clipboard.writeText(text).then(() => showToast(t('copied')));
728→  } else {
729→    fallbackCopy(text);
730→  }
731→}
732→
733→function fallbackCopy(text) {
734→  const ta = document.createElement('textarea');
735→  ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
736→  document.body.appendChild(ta); ta.select();
737→  document.execCommand('copy');
738→  document.body.removeChild(ta);
739→  showToast(t('copied'));
740→}
741→
742→function reverseGeocode(lat, lon, targetId) {
743→  const lang = currentLang === 'el' ? 'el' : 'en';
744→  fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}&accept-language=${lang}`, {
745→    headers: { 'User-Agent': 'TopoTools/1.0' }
746→  })
747→  .then(r => r.json())
748→  .then(data => {
749→    if (data.display_name) {
750→      document.getElementById(targetId).textContent = t('address_label') + ': ' + data.display_name;
751→    }
752→  })
753→  .catch(() => {});
754→}
755→
756→function downloadFile(content, filename, mime) {
757→  const blob = new Blob([content], { type: mime });
758→  const a = document.createElement('a');
759→  a.href = URL.createObjectURL(blob);
760→  a.download = filename;
761→  a.click();
762→  URL.revokeObjectURL(a.href);
763→}
764→
765→/* ========================================================================
766→   COORDINATE MATH (client-side, mirrors Python backend)
767→   ======================================================================== */
768→const GRS80_A = 6378137.0, GRS80_F = 1/298.257222101;
769→const GRS80_E2 = 2*GRS80_F - GRS80_F*GRS80_F;
770→const GRS80_EP2 = GRS80_E2 / (1 - GRS80_E2);
771→
772→const WGS84_A = 6378137.0, WGS84_F = 1/298.257223563;
773→const WGS84_E2 = 2*WGS84_F - WGS84_F*WGS84_F;
774→const WGS84_EP2 = WGS84_E2 / (1 - WGS84_E2);
775→
776→const TM_LON0 = 24 * Math.PI / 180, TM_K0 = 0.9996, TM_FE = 500000, TM_FN = 0;
777→const DX = -199.87, DY = 74.79, DZ = 246.62;
778→
779→function meridionalArc(phi, a, e2) {
780→  const e4 = e2*e2, e6 = e4*e2;
781→  const A0 = 1 - e2/4 - 3*e4/64 - 5*e6/256;
782→  const A2 = 3/8*(e2 + e4/4 + 15*e6/128);
783→  const A4 = 15/256*(e4 + 3*e6/4);
784→  const A6 = 35*e6/3072;
785→  return a*(A0*phi - A2*Math.sin(2*phi) + A4*Math.sin(4*phi) - A6*Math.sin(6*phi));
786→}
787→
788→function footpointLat(M, a, e2) {
789→  const e4 = e2*e2, e6 = e4*e2;
790→  const A0 = 1 - e2/4 - 3*e4/64 - 5*e6/256;
791→  const mu = M/(a*A0);
792→  const e1 = (1 - Math.sqrt(1-e2))/(1 + Math.sqrt(1-e2));
793→  const e12 = e1*e1, e13 = e12*e1, e14 = e13*e1;
794→  return mu + (3*e1/2 - 27*e13/32)*Math.sin(2*mu)
795→    + (21*e12/16 - 55*e14/32)*Math.sin(4*mu)
796→    + (151*e13/96)*Math.sin(6*mu)
797→    + (1097*e14/512)*Math.sin(8*mu);
798→}
799→
800→function tmForward(latR, lonR, a, e2, ep2, lon0, k0, fe, fn) {
801→  const phi = latR, dlam = lonR - lon0;
802→  const sp = Math.sin(phi), cp = Math.cos(phi), tp = Math.tan(phi);
803→  const N = a/Math.sqrt(1 - e2*sp*sp);
804→  const T = tp*tp, C = ep2*cp*cp, A = dlam*cp;
805→  const M = meridionalArc(phi, a, e2);
806→  const A2=A*A, A3=A2*A, A4=A3*A, A5=A4*A, A6=A5*A;
807→  const easting = fe + k0*N*(A + A3/6*(1-T+C) + A5/120*(5-18*T+T*T+72*C-58*ep2));
808→  const northing = fn + k0*(M + N*tp*(A2/2 + A4/24*(5-T+9*C+4*C*C) + A6/720*(61-58*T+T*T+600*C-330*ep2)));
809→  return [easting, northing];
810→}
811→
812→function tmReverse(easting, northing, a, e2, ep2, lon0, k0, fe, fn) {
813→  const M = (northing - fn)/k0;
814→  const phi1 = footpointLat(M, a, e2);
815→  const sp = Math.sin(phi1), cp = Math.cos(phi1), tp = Math.tan(phi1);
816→  const N1 = a/Math.sqrt(1 - e2*sp*sp);
817→  const R1 = a*(1-e2)/Math.pow(1-e2*sp*sp, 1.5);
818→  const T1 = tp*tp, C1 = ep2*cp*cp;
819→  const D = (easting - fe)/(N1*k0);
820→  const D2=D*D, D3=D2*D, D4=D3*D, D5=D4*D, D6=D5*D;
821→  const lat = phi1 - (N1*tp/R1)*(D2/2 - D4/24*(5+3*T1+10*C1-4*C1*C1-9*ep2) + D6/720*(61+90*T1+298*C1+45*T1*T1-252*ep2-3*C1*C1));
822→  const lon = lon0 + (1/cp)*(D - D3/6*(1+2*T1+C1) + D5/120*(5-2*C1+28*T1-3*C1*C1+8*ep2+24*T1*T1));
823→  return [lat, lon];
824→}
825→
826→function geoToECEF(latR, lonR, h, a, e2) {
827→  const sp = Math.sin(latR), cp = Math.cos(latR);
828→  const N = a/Math.sqrt(1 - e2*sp*sp);
829→  return [(N+h)*cp*Math.cos(lonR), (N+h)*cp*Math.sin(lonR), (N*(1-e2)+h)*sp];
830→}
831→
832→function ecefToGeo(X, Y, Z, a, e2) {
833→  const b = a*Math.sqrt(1-e2), ep2b = (a*a-b*b)/(b*b);
834→  const p = Math.sqrt(X*X+Y*Y);
835→  const lon = Math.atan2(Y, X);
836→  let theta = Math.atan2(Z*a, p*b);
837→  let lat = Math.atan2(Z + ep2b*b*Math.pow(Math.sin(theta),3), p - e2*a*Math.pow(Math.cos(theta),3));
838→  for (let i = 0; i < 10; i++) {
839→    const sl = Math.sin(lat), N = a/Math.sqrt(1-e2*sl*sl);
840→    const nl = Math.atan2(Z + e2*N*sl, p);
841→    if (Math.abs(nl-lat) < 1e-14) break;
842→    lat = nl;
843→  }
844→  return [lat, lon];
845→}
846→
847→// Public conversion functions
848→function egsa87ToWgs84(x, y) {
849→  const [latG, lonG] = tmReverse(x, y, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
850→  let [X, Y2, Z] = geoToECEF(latG, lonG, 0, GRS80_A, GRS80_E2);
851→  X += DX; Y2 += DY; Z += DZ;
852→  const [lat, lon] = ecefToGeo(X, Y2, Z, WGS84_A, WGS84_E2);
853→  return [lat*180/Math.PI, lon*180/Math.PI];
854→}
855→
856→function wgs84ToEgsa87(lat, lon) {
857→  const latR = lat*Math.PI/180, lonR = lon*Math.PI/180;
858→  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, WGS84_A, WGS84_E2);
859→  X -= DX; Y2 -= DY; Z -= DZ;
860→  const [latG, lonG] = ecefToGeo(X, Y2, Z, GRS80_A, GRS80_E2);
861→  return tmForward(latG, lonG, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
862→}
863→
864→function wgs84ToTm07(lat, lon) {
865→  return tmForward(lat*Math.PI/180, lon*Math.PI/180, WGS84_A, WGS84_E2, WGS84_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
866→}
867→
868→function tm07ToWgs84(x, y) {
869→  const [lat, lon] = tmReverse(x, y, WGS84_A, WGS84_E2, WGS84_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
870→  return [lat*180/Math.PI, lon*180/Math.PI];
871→}
872→
873→// GGRS87 geographic (degrees on GRS80) <-> WGS84
874→function ggrs87ToWgs84(latDeg, lonDeg) {
875→  const latR = latDeg*Math.PI/180, lonR = lonDeg*Math.PI/180;
876→  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, GRS80_A, GRS80_E2);
877→  X += DX; Y2 += DY; Z += DZ;
878→  const [lat, lon] = ecefToGeo(X, Y2, Z, WGS84_A, WGS84_E2);
879→  return [lat*180/Math.PI, lon*180/Math.PI];
880→}
881→
882→function wgs84ToGgrs87(lat, lon) {
883→  const latR = lat*Math.PI/180, lonR = lon*Math.PI/180;
884→  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, WGS84_A, WGS84_E2);
885→  X -= DX; Y2 -= DY; Z -= DZ;
886→  const [latG, lonG] = ecefToGeo(X, Y2, Z, GRS80_A, GRS80_E2);
887→  return [latG*180/Math.PI, lonG*180/Math.PI];
888→}
889→
890→// EGSA87 <-> GGRS87 geographic (just TM forward/reverse on GRS80)
891→function egsa87ToGgrs87Geo(x, y) {
892→  const [lat, lon] = tmReverse(x, y, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
893→  return [lat*180/Math.PI, lon*180/Math.PI];
894→}
895→function ggrs87GeoToEgsa87(latDeg, lonDeg) {
896→  return tmForward(latDeg*Math.PI/180, lonDeg*Math.PI/180, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
897→}
898→
899→// DMS parsing/formatting

