  const ta = document.createElement('textarea');
  ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
  document.body.appendChild(ta); ta.select();
  document.execCommand('copy');
  document.body.removeChild(ta);
  showToast(t('copied'));
}

function reverseGeocode(lat, lon, targetId) {
  const lang = currentLang === 'el' ? 'el' : 'en';
  fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}&accept-language=${lang}`, {
    headers: { 'User-Agent': 'TopoTools/1.0' }
  })
  .then(r => r.json())
  .then(data => {
    if (data.display_name) {
      document.getElementById(targetId).textContent = t('address_label') + ': ' + data.display_name;
    }
  })
  .catch(() => {});
}

function downloadFile(content, filename, mime) {
  const blob = new Blob([content], { type: mime });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
}

/* ========================================================================
   COORDINATE MATH (client-side, mirrors Python backend)
   ======================================================================== */
const GRS80_A = 6378137.0, GRS80_F = 1/298.257222101;
const GRS80_E2 = 2*GRS80_F - GRS80_F*GRS80_F;
const GRS80_EP2 = GRS80_E2 / (1 - GRS80_E2);

const WGS84_A = 6378137.0, WGS84_F = 1/298.257223563;
const WGS84_E2 = 2*WGS84_F - WGS84_F*WGS84_F;
const WGS84_EP2 = WGS84_E2 / (1 - WGS84_E2);

const TM_LON0 = 24 * Math.PI / 180, TM_K0 = 0.9996, TM_FE = 500000, TM_FN = 0;
const DX = -199.87, DY = 74.79, DZ = 246.62;

function meridionalArc(phi, a, e2) {
  const e4 = e2*e2, e6 = e4*e2;
  const A0 = 1 - e2/4 - 3*e4/64 - 5*e6/256;
  const A2 = 3/8*(e2 + e4/4 + 15*e6/128);
  const A4 = 15/256*(e4 + 3*e6/4);
  const A6 = 35*e6/3072;
  return a*(A0*phi - A2*Math.sin(2*phi) + A4*Math.sin(4*phi) - A6*Math.sin(6*phi));
}

function footpointLat(M, a, e2) {
  const e4 = e2*e2, e6 = e4*e2;
  const A0 = 1 - e2/4 - 3*e4/64 - 5*e6/256;
  const mu = M/(a*A0);
  const e1 = (1 - Math.sqrt(1-e2))/(1 + Math.sqrt(1-e2));
  const e12 = e1*e1, e13 = e12*e1, e14 = e13*e1;
  return mu + (3*e1/2 - 27*e13/32)*Math.sin(2*mu)
    + (21*e12/16 - 55*e14/32)*Math.sin(4*mu)
    + (151*e13/96)*Math.sin(6*mu)
    + (1097*e14/512)*Math.sin(8*mu);
}

function tmForward(latR, lonR, a, e2, ep2, lon0, k0, fe, fn) {
  const phi = latR, dlam = lonR - lon0;
  const sp = Math.sin(phi), cp = Math.cos(phi), tp = Math.tan(phi);
  const N = a/Math.sqrt(1 - e2*sp*sp);
  const T = tp*tp, C = ep2*cp*cp, A = dlam*cp;
  const M = meridionalArc(phi, a, e2);
  const A2=A*A, A3=A2*A, A4=A3*A, A5=A4*A, A6=A5*A;
  const easting = fe + k0*N*(A + A3/6*(1-T+C) + A5/120*(5-18*T+T*T+72*C-58*ep2));
  const northing = fn + k0*(M + N*tp*(A2/2 + A4/24*(5-T+9*C+4*C*C) + A6/720*(61-58*T+T*T+600*C-330*ep2)));
  return [easting, northing];
}

function tmReverse(easting, northing, a, e2, ep2, lon0, k0, fe, fn) {
  const M = (northing - fn)/k0;
  const phi1 = footpointLat(M, a, e2);
  const sp = Math.sin(phi1), cp = Math.cos(phi1), tp = Math.tan(phi1);
  const N1 = a/Math.sqrt(1 - e2*sp*sp);
  const R1 = a*(1-e2)/Math.pow(1-e2*sp*sp, 1.5);
  const T1 = tp*tp, C1 = ep2*cp*cp;
  const D = (easting - fe)/(N1*k0);
  const D2=D*D, D3=D2*D, D4=D3*D, D5=D4*D, D6=D5*D;
  const lat = phi1 - (N1*tp/R1)*(D2/2 - D4/24*(5+3*T1+10*C1-4*C1*C1-9*ep2) + D6/720*(61+90*T1+298*C1+45*T1*T1-252*ep2-3*C1*C1));
  const lon = lon0 + (1/cp)*(D - D3/6*(1+2*T1+C1) + D5/120*(5-2*C1+28*T1-3*C1*C1+8*ep2+24*T1*T1));
  return [lat, lon];
}

function geoToECEF(latR, lonR, h, a, e2) {
  const sp = Math.sin(latR), cp = Math.cos(latR);
  const N = a/Math.sqrt(1 - e2*sp*sp);
  return [(N+h)*cp*Math.cos(lonR), (N+h)*cp*Math.sin(lonR), (N*(1-e2)+h)*sp];
}

function ecefToGeo(X, Y, Z, a, e2) {
  const b = a*Math.sqrt(1-e2), ep2b = (a*a-b*b)/(b*b);
  const p = Math.sqrt(X*X+Y*Y);
  const lon = Math.atan2(Y, X);
  let theta = Math.atan2(Z*a, p*b);
  let lat = Math.atan2(Z + ep2b*b*Math.pow(Math.sin(theta),3), p - e2*a*Math.pow(Math.cos(theta),3));
  for (let i = 0; i < 10; i++) {
    const sl = Math.sin(lat), N = a/Math.sqrt(1-e2*sl*sl);
    const nl = Math.atan2(Z + e2*N*sl, p);
    if (Math.abs(nl-lat) < 1e-14) break;
    lat = nl;
  }
  return [lat, lon];
}

// Public conversion functions
function egsa87ToWgs84(x, y) {
  const [latG, lonG] = tmReverse(x, y, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
  let [X, Y2, Z] = geoToECEF(latG, lonG, 0, GRS80_A, GRS80_E2);
  X += DX; Y2 += DY; Z += DZ;
  const [lat, lon] = ecefToGeo(X, Y2, Z, WGS84_A, WGS84_E2);
  return [lat*180/Math.PI, lon*180/Math.PI];
}

function wgs84ToEgsa87(lat, lon) {
  const latR = lat*Math.PI/180, lonR = lon*Math.PI/180;
  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, WGS84_A, WGS84_E2);
  X -= DX; Y2 -= DY; Z -= DZ;
  const [latG, lonG] = ecefToGeo(X, Y2, Z, GRS80_A, GRS80_E2);
  return tmForward(latG, lonG, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
}

function wgs84ToTm07(lat, lon) {
  return tmForward(lat*Math.PI/180, lon*Math.PI/180, WGS84_A, WGS84_E2, WGS84_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
}

function tm07ToWgs84(x, y) {
  const [lat, lon] = tmReverse(x, y, WGS84_A, WGS84_E2, WGS84_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
  return [lat*180/Math.PI, lon*180/Math.PI];
}

// GGRS87 geographic (degrees on GRS80) <-> WGS84
function ggrs87ToWgs84(latDeg, lonDeg) {
  const latR = latDeg*Math.PI/180, lonR = lonDeg*Math.PI/180;
  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, GRS80_A, GRS80_E2);
  X += DX; Y2 += DY; Z += DZ;
  const [lat, lon] = ecefToGeo(X, Y2, Z, WGS84_A, WGS84_E2);
  return [lat*180/Math.PI, lon*180/Math.PI];
}

function wgs84ToGgrs87(lat, lon) {
  const latR = lat*Math.PI/180, lonR = lon*Math.PI/180;
  let [X, Y2, Z] = geoToECEF(latR, lonR, 0, WGS84_A, WGS84_E2);
  X -= DX; Y2 -= DY; Z -= DZ;
  const [latG, lonG] = ecefToGeo(X, Y2, Z, GRS80_A, GRS80_E2);
  return [latG*180/Math.PI, lonG*180/Math.PI];
}

// EGSA87 <-> GGRS87 geographic (just TM forward/reverse on GRS80)
function egsa87ToGgrs87Geo(x, y) {
  const [lat, lon] = tmReverse(x, y, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
  return [lat*180/Math.PI, lon*180/Math.PI];
}
function ggrs87GeoToEgsa87(latDeg, lonDeg) {
  return tmForward(latDeg*Math.PI/180, lonDeg*Math.PI/180, GRS80_A, GRS80_E2, GRS80_EP2, TM_LON0, TM_K0, TM_FE, TM_FN);
}

