  if (m[4] && /[SsWw]/.test(m[4])) dd = -dd;
  if (parseInt(m[1]) < 0) dd = -dd + 2*parseInt(m[1]); // handle negative
  return dd;
}

function toDMS(dd, dir) {
  const sign = dd < 0 ? -1 : 1;
  dd = Math.abs(dd);
  const d = Math.floor(dd);
  const mf = (dd - d)*60;
  const m = Math.floor(mf);
  const s = ((mf - m)*60).toFixed(4);
  const suffix = dir === 'lat' ? (sign >= 0 ? 'N' : 'S') : (sign >= 0 ? 'E' : 'W');
  return d + '\u00B0 ' + String(m).padStart(2,'0') + '\u2032 ' + String(s).padStart(7,'0') + '\u2033 ' + suffix;
}

// Validation
function isValidWgs84(lat, lon) { return lat >= 34 && lat <= 42 && lon >= 19 && lon <= 30; }
function isLikelyGreekGrid(x, y) { return x >= 100000 && x <= 900000 && y >= 3800000 && y <= 4700000; }

/* ========================================================================
   HUB CONVERSION: input -> GGRS87 geo -> all outputs
   ======================================================================== */
function inputToGgrs87Geo(system, v1, v2) {
  switch(system) {
    case 'egsa87': return egsa87ToGgrs87Geo(v1, v2);
    case 'wgs84_dd': { const [g1,g2] = wgs84ToGgrs87(v1, v2); return [g1, g2]; }
    case 'wgs84_dms': {
      const lat = typeof v1 === 'string' ? parseDMS(v1) : v1;
      const lon = typeof v2 === 'string' ? parseDMS(v2) : v2;
      return wgs84ToGgrs87(lat, lon);
    }
    case 'ggrs87_geo': return [v1, v2];
    case 'htrs07_geo': {
      // HTRS07 geo is WGS84 geographic
      return wgs84ToGgrs87(v1, v2);
    }
    case 'tm07': {
      const [lat, lon] = tm07ToWgs84(v1, v2);
      return wgs84ToGgrs87(lat, lon);
    }
