  }
}

function ggrs87GeoToAll(gLat, gLon) {
  const [wLat, wLon] = ggrs87ToWgs84(gLat, gLon);
  const [eX, eY] = ggrs87GeoToEgsa87(gLat, gLon);
  const [tX, tY] = wgs84ToTm07(wLat, wLon);
  return {
    egsa87: { x: eX, y: eY },
    wgs84_dd: { lat: wLat, lon: wLon },
    wgs84_dms: { lat: toDMS(wLat, 'lat'), lon: toDMS(wLon, 'lon') },
    ggrs87_geo: { lat: gLat, lon: gLon },
    htrs07_geo: { lat: wLat, lon: wLon },
    tm07: { x: tX, y: tY },
  };
