"""Claude AI property report generation."""

import os
import json
import anthropic


def _format_layer_data(building_raw: dict, natura: list, archaeological: list,
                       forest: list, shoreline: list, zoe: list,
                       kaek_info: dict) -> str:
    """Format all TEE layer data into a structured text block for Claude."""
    parts = []

    parts.append(f"KAEK: {kaek_info.get('kaek', 'N/A')}")
    if kaek_info.get("area_m2"):
        parts.append(f"Area: {kaek_info['area_m2']} m²")
    if kaek_info.get("lat") and kaek_info.get("lon"):
        parts.append(f"Coordinates: {kaek_info['lat']:.6f}, {kaek_info['lon']:.6f}")

    # Building params from TEE
    for key, features in building_raw.items():
        if features:
            attrs = features[0].get("attributes", {}) if features else {}
            label = attrs.get("LABEL") or attrs.get("label")
            if label:
                parts.append(f"Building layer '{key}': {label}")
            if attrs:
                for k, v in attrs.items():
                    if v and k not in ("OBJECTID", "Shape", "SHAPE", "LABEL", "label"):
                        parts.append(f"  {k}: {v}")

    if natura:
        parts.append(f"\nNATURA 2000 ZONES ({len(natura)} found):")
        for f in natura:
            a = f.get("attributes", {})
            parts.append(f"  - {a.get('SITE_NAME') or a.get('SITENAME') or 'Unknown'}")

    if archaeological:
        parts.append(f"\nARCHAEOLOGICAL ZONES ({len(archaeological)} found):")
        for f in archaeological:
            a = f.get("attributes", {})
            cat = f.get("_category", "unknown")
            parts.append(f"  - {a.get('NAME') or a.get('ONOMASIA') or 'Unknown'} ({cat})")

    if forest:
        parts.append(f"\nFOREST MAP: {len(forest)} overlap(s) found")

    if shoreline:
        parts.append(f"\nSHORELINE: Within shoreline buffer zone")

    if zoe:
        parts.append(f"\nZOE (out-of-plan regulation) ZONES ({len(zoe)} found):")
        for f in zoe:
            a = f.get("attributes", {})
            parts.append(f"  - {a.get('LABEL') or a.get('ZONE_NAME') or 'ZOE zone'}")

    if not natura and not archaeological and not forest and not shoreline and not zoe:
        parts.append("\nNo environmental or archaeological restrictions found.")

    return "\n".join(parts)


async def generate_property_report(
    building_raw: dict,
    natura: list,
    archaeological: list,
    forest: list,
    shoreline: list,
    zoe: list,
    kaek_info: dict,
) -> str:
    """Generate an AI property due diligence report using Claude."""
    layer_data = _format_layer_data(
        building_raw, natura, archaeological, forest, shoreline, zoe, kaek_info
    )

    client = anthropic.Anthropic(api_key=os.environ.get("ANTHROPIC_API_KEY", ""))

    message = client.messages.create(
        model="claude-sonnet-4-20250514",
        max_tokens=2000,
        messages=[
            {
                "role": "user",
                "content": f"""You are an expert Greek property surveyor assistant. Based on the following government data retrieved from TEE (Technical Chamber of Greece) and the National Cadastre, generate a professional property due diligence report in Greek.

The report should include:
1. **Περίληψη** (Executive Summary) - 2-3 sentences on the property's overall status
2. **Πολεοδομικά Στοιχεία** (Zoning Data) - Building parameters, coverage, height, building factor etc.
3. **Περιβαλλοντικοί Περιορισμοί** (Environmental Restrictions) - Natura 2000, forest, shoreline
4. **Αρχαιολογικοί Περιορισμοί** (Archaeological Restrictions)
5. **Κανονιστικό Πλαίσιο** (Regulatory Framework) - ZOE zones, FEK references
6. **Συστάσεις** (Recommendations) - What the property owner/buyer should do next

Use professional but clear language. Be specific with numbers and zone names from the data.
If data is missing for a section, note that the information was not available from TEE services.

RAW GOVERNMENT DATA:
{layer_data}"""
            }
        ],
    )

    return message.content[0].text

