a.fek-link { color: var(--accent); text-decoration: none; }
a.fek-link:hover { text-decoration: underline; }

/* ========================================================================
   AI REPORT
   ======================================================================== */
.report-output {
  font-size: 14px; line-height: 1.7;
  white-space: pre-wrap; word-wrap: break-word;
}
.report-output h1, .report-output h2, .report-output h3 {
  margin-top: 16px; margin-bottom: 8px; color: var(--text);
}
.report-output h2 { font-size: 16px; border-bottom: 1px solid var(--border); padding-bottom: 4px; }
.report-output h3 { font-size: 14px; }
.report-output strong { color: var(--text); }
.report-output ul, .report-output ol { padding-left: 20px; margin: 8px 0; }
.report-output li { margin-bottom: 4px; }

.report-status {
  display: flex; align-items: center; gap: 10px;
  padding: 12px 16px; border-radius: 8px; margin-bottom: 12px;
  font-weight: 600; font-size: 14px;
}
.report-status.loading {
  background: rgba(37, 99, 235, 0.1); border: 1px solid var(--accent);
  color: var(--accent);
}
.report-status.done {
  background: rgba(34, 197, 94, 0.1); border: 1px solid var(--green);
  color: var(--green);
}
.report-status.error {
  background: rgba(239, 68, 68, 0.1); border: 1px solid var(--red);
  color: var(--red);
}
.report-status .dot-pulse {
  display: inline-block; width: 8px; height: 8px;
  border-radius: 50%; background: var(--accent);
  animation: pulse 1.2s ease-in-out infinite;
}
@keyframes pulse { 0%, 100% { opacity: 0.3; } 50% { opacity: 1; } }

.restriction-badge {
  display: inline-block; padding: 3px 10px; border-radius: 12px;
  font-size: 12px; font-weight: 600; font-family: 'IBM Plex Mono', monospace;
}
.restriction-badge.clean { background: rgba(34,197,94,0.15); color: var(--green); }
.restriction-badge.flagged { background: rgba(239,68,68,0.15); color: var(--red); }

