/* ========================================================================
   REPORT TAB
   ======================================================================== */
let reportMap = null;

function simpleMarkdown(md) {
  // Minimal markdown -> HTML: headers, bold, lists, paragraphs
  let html = md
    .replace(/^### (.+)$/gm, '<h3>$1</h3>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^\- (.+)$/gm, '<li>$1</li>')
    .replace(/^\* (.+)$/gm, '<li>$1</li>')
    .replace(/^\d+\. (.+)$/gm, '<li>$1</li>');
  // Wrap consecutive <li> in <ul>
  html = html.replace(/((?:<li>.*<\/li>\n?)+)/g, '<ul>$1</ul>');
  // Paragraphs for remaining text
  html = html.replace(/\n\n/g, '</p><p>');
  return '<p>' + html + '</p>';
}

function doGenerateReport() {
  let kaek = document.getElementById('report-kaek').value.trim();
  kaek = kaek.replace(/^KAEK\s*/i, '').replace(/^ΚΑΕΚ\s*/i, '').trim();
  if (!kaek) return;

  const btn = document.getElementById('report-btn');
  btn.disabled = true;

  // Show loading
  const statusBar = document.getElementById('report-status-bar');
  statusBar.style.display = '';
  statusBar.innerHTML = `<div class="report-status loading"><span class="dot-pulse"></span> ${t('report_loading')}</div>`;
  document.getElementById('report-output').style.display = 'none';

  fetch('/api/v1/report/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ kaek }),
  })
  .then(r => {
    if (!r.ok) return r.json().then(e => { throw new Error(e.detail || 'Request failed'); });
    return r.json();
  })
  .then(data => {
    statusBar.innerHTML = `<div class="report-status done">${t('report_done')}</div>`;

    // Meta grid
    const coordsStr = data.x != null ? `${data.x.toFixed(2)}, ${data.y.toFixed(2)}` : '-';
    document.getElementById('report-meta').innerHTML = `
      <div class="meta-item"><label>KAEK</label><div class="meta-value">${escapeHtml(data.kaek)}</div></div>
      <div class="meta-item"><label>EGSA87</label><div class="meta-value">${coordsStr}</div></div>
      ${data.area_m2 ? '<div class="meta-item"><label>' + t('plot_area') + '</label><div class="meta-value">' + data.area_m2.toFixed(2) + ' m\u00B2</div></div>' : ''}
    `;

    // Restriction badge
    const badge = document.getElementById('report-restriction-badge');
    if (data.has_restrictions) {
      badge.className = 'restriction-badge flagged';
      badge.textContent = t('has_restrictions');
    } else {
      badge.className = 'restriction-badge clean';
      badge.textContent = t('no_restrictions');
    }

    // Report content (markdown -> HTML)
    document.getElementById('report-content').innerHTML = simpleMarkdown(data.report_md);

    // Map
    if (data.lat && data.lon) {
      document.getElementById('report-output').style.display = '';
      setTimeout(() => {
        const container = document.getElementById('report-map');
        if (reportMap) { reportMap.remove(); reportMap = null; }
        reportMap = L.map(container).setView([data.lat, data.lon], 16);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
          attribution: '&copy; OpenStreetMap', maxZoom: 19
        }).addTo(reportMap);
        const color = data.has_restrictions ? '#ef4444' : '#22c55e';
        L.circleMarker([data.lat, data.lon], { radius: 8, color, fillColor: color, fillOpacity: 0.8, weight: 2 }).addTo(reportMap);
        L.circle([data.lat, data.lon], { radius: 100, color, fillOpacity: 0.08, weight: 1 }).addTo(reportMap);
        reportMap.invalidateSize();
        reverseGeocode(data.lat, data.lon, 'report-address');
      }, 50);
    }

    document.getElementById('report-output').style.display = '';
  })
  .catch(err => {
    statusBar.innerHTML = `<div class="report-status error">${t('report_error')}: ${escapeHtml(err.message)}</div>`;
  })
  .finally(() => { btn.disabled = false; });
}

function copyReport() {
  const content = document.getElementById('report-content').innerText;
  copyValue(content);
}

